/// no `/`. Any other ID is returned unchanged.
fn resource_id(lowered: &str) -> Option<&str> {
    if lowered.starts_with("arn:") {
        lowered.rsplit_once('/').map(|(_, resource)| resource)
    } else {
        Some(lowered)
